set -x

# Generated by examples/data_preprocess/drmas_math.py
DATA_DIR=/work/data/drmas_math
TRAIN_DATA="$DATA_DIR/train.parquet"
MODE=train
if [[ ${1:-} == train || ${1:-} == eval || ${1:-} == evaluation ]]; then
    MODE=$1
    shift
fi
run_id=
if (( $# )); then
    if [[ $# != 2 || $1 != --run-id || ! $2 =~ ^[a-zA-Z0-9][a-zA-Z0-9._-]*$ ]]; then
        echo "Usage: bash examples/drmas_trainer/run_math.sh [train|eval] [--run-id NAME]" >&2
        exit 2
    fi
    run_id=$2
fi
if [ "$MODE" == "eval" ] || [ "$MODE" == "evaluation" ]; then
    echo "Running in evaluation mode"
    VAL_ONLY=True
    VAL_DATA="$DATA_DIR/test.parquet" # Full test dataset
    train_data_size=32
    val_data_size=64
    val_group_size=16  # For pass@16 and avg@16 computation during evaluation
else
    echo "Running in training mode"
    VAL_ONLY=False
    VAL_DATA="$DATA_DIR/test_sampled.parquet" # For fast validation during training (test_sampled.parquet contains 50 examples from MATH500, 30 examples from AIME2024, and 30 examples from AIME2025)
    train_data_size=32
    val_data_size=110
    val_group_size=1
fi

###################### Algorithm Configurations #################
algorithm=grpo
group_size=8
group_by_agent_id=True # enable Dr. MAS

##################### Agent Configurations #####################
agent_ids='["Solver Agent","Verifier Agent"]'
model_ids='["/data1/training/models/Qwen3-4B","/data1/training/models/Qwen3-4B"]'
model_sharing=False

orchestra_type=math
max_loop_num=2

# Agent-specific parameter override (only support actor_rollout_ref)
actor_optim_lr='[1e-6,1e-6]'
actor_ppo_micro_batch_size_per_gpu='[2,2]'

model_name_tag=$(jq -r '.[]' <<< "$model_ids"  | awk -F/ '{print $NF}' | tr '[:upper:]' '[:lower:]' | tr '-' '_' | paste -sd_)

ascend_math_rollout=False
actor_compile=True
if [[ "${ROLLOUT_BACKEND:-vllm}" == vllm && "${TRAINER_DEVICE:-npu}" == npu ]]; then
    ascend_math_rollout=True
    actor_compile=False
    if [[ -r /usr/local/Ascend/ascend-toolkit/set_env.sh ]]; then
        source /usr/local/Ascend/ascend-toolkit/set_env.sh
    fi
fi

experiment_name="drmas_share${model_sharing}_${model_name_tag}"

tensorboard_root="${TENSORBOARD_ROOT:-/work/DrMAS/tensorboard_log}/${experiment_name}"
mkdir -p -- "$tensorboard_root" || exit 1
checkpoint_dir="/work/DrMAS/checkpoints/DrMAS_math/$experiment_name"
unset DRMAS_TB_PURGE_STEP
if [[ -n $run_id ]]; then
    checkpoint_dir="$checkpoint_dir/$run_id"
    TENSORBOARD_DIR="$tensorboard_root/$run_id"
    mkdir -p -- "$checkpoint_dir" "$TENSORBOARD_DIR" || exit 1
    exec 9>"$checkpoint_dir/.run.lock" || exit 1
    flock -n 9 || { echo "Run $run_id is already active" >&2; exit 1; }
    if [[ $MODE == train ]]; then
        tracker="$checkpoint_dir/latest_checkpointed_iteration.txt"
        if [[ -f $tracker ]]; then
            last_step=$(cat "$tracker") || exit 1
            [[ $last_step =~ ^[0-9]+$ && -d "$checkpoint_dir/global_step_$last_step" ]] || { echo "Invalid checkpoint tracker: $tracker" >&2; exit 1; }
            export DRMAS_TB_PURGE_STEP=$((10#$last_step + 1))
        elif compgen -G "$TENSORBOARD_DIR/events.out.tfevents.*" >/dev/null; then
            export DRMAS_TB_PURGE_STEP=0
        fi
    else
        TENSORBOARD_DIR="$TENSORBOARD_DIR/eval"
    fi
else
    TENSORBOARD_DIR=$(mktemp -d -- "$tensorboard_root/$(date +%Y%m%d-%H%M%S)-XXXXXX") || exit 1
fi
echo "Checkpoint directory: $checkpoint_dir"
export TENSORBOARD_DIR
echo "TensorBoard directory: $TENSORBOARD_DIR"

python3 -m verl.trainer.main_ppo \
    algorithm.adv_estimator=$algorithm \
    data.train_files=$TRAIN_DATA \
    ++data.dataloader_num_workers=0 \
    data.val_files=$VAL_DATA \
    data.train_batch_size=$train_data_size \
    data.val_batch_size=$val_data_size \
    data.max_prompt_length=8192 \
    data.max_response_length=4096 \
    data.filter_overlong_prompts=True \
    +data.apply_chat_template_kwargs.enable_thinking=False \
    data.truncation='middle' \
    data.return_raw_chat=True \
    actor_rollout_ref.model.path=null \
    actor_rollout_ref.actor.optim.lr=null \
    +agent.agent_specific_parameters.actor.optim.lr=$actor_optim_lr \
    actor_rollout_ref.model.use_remove_padding=True \
    actor_rollout_ref.actor.use_adaptive_ppo_mini_batch_size=True \
    actor_rollout_ref.actor.ppo_mini_update_num=1 \
    actor_rollout_ref.actor.ppo_micro_batch_size_per_gpu=null \
    +agent.agent_specific_parameters.actor.ppo_micro_batch_size_per_gpu=$actor_ppo_micro_batch_size_per_gpu \
    actor_rollout_ref.actor.use_torch_compile=$actor_compile \
    actor_rollout_ref.actor.use_kl_loss=False \
    actor_rollout_ref.actor.entropy_coeff=0.0 \
    actor_rollout_ref.model.enable_gradient_checkpointing=True \
    actor_rollout_ref.actor.fsdp_config.param_offload=False \
    actor_rollout_ref.actor.fsdp_config.optimizer_offload=True \
    actor_rollout_ref.rollout.log_prob_micro_batch_size_per_gpu=4 \
    actor_rollout_ref.rollout.tensor_model_parallel_size=1 \
    +actor_rollout_ref.rollout.ascend_math_rollout=$ascend_math_rollout \
    actor_rollout_ref.rollout.name="${ROLLOUT_BACKEND:-vllm}" \
    actor_rollout_ref.rollout.gpu_memory_utilization=0.5 \
    actor_rollout_ref.rollout.max_num_batched_tokens=12288 \
    actor_rollout_ref.rollout.enable_chunked_prefill=True \
    actor_rollout_ref.rollout.enforce_eager=False \
    actor_rollout_ref.rollout.free_cache_engine=False \
    actor_rollout_ref.rollout.val_kwargs.do_sample=True \
    actor_rollout_ref.rollout.val_kwargs.top_p=0.95 \
    actor_rollout_ref.rollout.val_kwargs.temperature=0.6 \
    actor_rollout_ref.actor.use_invalid_action_penalty=True \
    actor_rollout_ref.actor.invalid_action_penalty_coef=0.1 \
    algorithm.group_by_agent_id=$group_by_agent_id \
    env.env_name=math \
    env.seed=0 \
    env.rollout.n=$group_size \
    env.rollout.val_n=$val_group_size \
    agent.agent_ids="$agent_ids" \
    agent.model_ids="$model_ids" \
    agent.model_sharing=$model_sharing \
    agent.orchestra_type=$orchestra_type \
    agent.orchestra.math.max_loop_num=$max_loop_num \
    trainer.critic_warmup=0 \
    trainer.logger=['console','tensorboard'] \
    trainer.project_name='DrMAS_math' \
    trainer.experiment_name="$experiment_name" \
    trainer.device="${TRAINER_DEVICE:-npu}" \
    trainer.n_gpus_per_node=4 \
    trainer.nnodes=1 \
    trainer.default_local_dir="$checkpoint_dir" \
    trainer.resume_mode=auto \
    trainer.save_freq=10 \
    trainer.max_actor_ckpt_to_keep=1 \
    trainer.test_freq=10 \
    trainer.total_epochs=2 \
    trainer.val_only=$VAL_ONLY \
    trainer.val_before_train=True
